    def test_vectors(self):
        with open(_vector_file(), encoding="utf-8") as fh:
            cases = json.load(fh)["cases"]
        bad = []
        for c in cases:
            label = "{}({})".format(c["fn"], ", ".join(_canon(a) for a in c["args"]))
            fn = getattr(lib, c["fn"], None)
            if fn is None:
                bad.append("missing function " + c["fn"])
                continue
            try:
