mod common;
use common::Json;
use std::panic::{catch_unwind, AssertUnwindSafe};

trait ToJ {
    fn j(&self) -> Json;
}
impl ToJ for i32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u8 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for i64 {
    fn j(&self) -> Json {
        Json::Int(*self)
    }
}
impl ToJ for bool {
    fn j(&self) -> Json {
        Json::Bool(*self)
    }
}
impl ToJ for String {
    fn j(&self) -> Json {
        Json::Str(self.clone())
    }
}
impl<T: ToJ> ToJ for Vec<T> {
    fn j(&self) -> Json {
        Json::Arr(self.iter().map(|x| x.j()).collect())
    }
}
impl<T: ToJ> ToJ for Option<T> {
    fn j(&self) -> Json {
        match self {
            Some(x) => x.j(),
            None => Json::Null,
        }
    }
}

fn call(f: &str, a: &[Json]) -> Option<Result<Json, ()>> {
    Some(match f {
        "region_sizes" => grid_regions::region_sizes(&a[0].list(&|e0| e0.string())).map(|v| v.j()).map_err(|_| ()),
        "region_at" => grid_regions::region_at(&a[0].list(&|e0| e0.string()), a[1].int_(), a[2].int_()).map(|v| v.j()).map_err(|_| ()),
        "largest_crop" => Ok(grid_regions::largest_crop(&a[0].list(&|e0| e0.string())).j()),
